#include <Arduino.h>
#include <DHT.h>
#include <TM1637Display.h>
#include <math.h>

DHT dht(7, DHT11);
TM1637Display display(4, 5);
uint8_t mode = 0;
int lightValue = 0;
float temperatureValue = NAN;
float humidityValue = NAN;
int lastRaw = HIGH;
int stableButton = HIGH;
unsigned long changedAt = 0;
unsigned long lastReport = 0;

void refreshSensors() {
  lightValue = analogRead(A0);
  float t = dht.readTemperature();
  float h = dht.readHumidity();
  if (!isnan(t)) temperatureValue = t;
  if (!isnan(h)) humidityValue = h;
}

void showSelected() {
  if (mode == 0) display.showNumberDec(lightValue);
  else {
    float v = mode == 1 ? temperatureValue : humidityValue;
    if (isnan(v)) {
      const uint8_t missing[4] = {0x40, 0x40, 0x40, 0x40};
      display.setSegments(missing);
    } else display.showNumberDec((int)round(v));
  }
}

void reportData() {
  Serial.print("Light: "); Serial.print(lightValue);
  Serial.print(" Temperature: "); Serial.print(temperatureValue, 1);
  Serial.print(" Humidity: "); Serial.println(humidityValue, 1);
  if (lightValue < 200 && !isnan(temperatureValue) && temperatureValue > 30) {
    Serial.println("Environment abnormal");
  }
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  Serial.begin(9600);
  dht.begin();
  display.setBrightness(4);
  refreshSensors();
  showSelected();
  lastReport = millis();
}

void loop() {
  unsigned long now = millis();
  int raw = digitalRead(2);
  if (raw != lastRaw) {
    lastRaw = raw;
    changedAt = now;
  }
  if (now - changedAt >= 30 && raw != stableButton) {
    stableButton = raw;
    if (stableButton == LOW) mode = (mode + 1) % 3;
  }
  lightValue = analogRead(A0);
  if (now - lastReport >= 2000) {
    lastReport = now;
    refreshSensors();
    reportData();
  }
  showSelected();
  delay(10);
}
